#!/usr/bin/env bash
# scripts/regenerated-patch.sh
#
# Carries regenerated bytes, as data, from a job that runs third-party code to
# a job that holds a push token.
#
# WHY. A rebuild of committed output (Public/vendor, the Chickadee extension,
# the xeus kernels) runs the install and build scripts of packages that a
# Dependabot PR has just bumped. A later step in the same job is not protected
# from them, even with no secret in the job environment: a build step can add
# a directory to $GITHUB_PATH (a fake `git` then runs with the token), set
# LD_PRELOAD or GIT_* through $GITHUB_ENV, write a git hook, or set
# `url.<base>.insteadOf` in .git/config so the push goes to another host. So
# the rebuild runs in a job with no token, and `make` writes its result as a
# patch. A second job, on a new runner where no third-party code has run,
# checks the patch with `apply` and pushes it.
#
#   scripts/regenerated-patch.sh make PATCH PATH...
#       Stage every change under PATH... (new, changed and deleted files) and
#       write it to PATCH as a binary patch. Changes outside PATH... are left
#       out. Prints `changed=true` or `changed=false`, for $GITHUB_OUTPUT.
#   scripts/regenerated-patch.sh apply PATCH PATH...
#       Refuse PATCH unless every file it touches is a regular file under one
#       of PATH... (a directory, or an exact file). Then apply it to the index
#       and the work tree.
#   scripts/regenerated-patch.sh --self-test
#
# The check in `apply` is the boundary. The patch was written by a job that
# ran untrusted code, so `apply` trusts nothing in it: not its paths, not its
# file modes. Its content inside PATH... is the regenerated output itself, and
# CI tests that like any other change on the PR.

set -euo pipefail

die() {
  echo "regenerated-patch: $*" >&2
  exit 1
}

# 0 when $1 is PATH, or inside PATH, for one of the remaining arguments.
path_allowed() {
  local path="$1" allowed
  shift
  case "$path" in
    /* | ../* | */../* | */.. | .. | .git/* | */.git/* | .git | */.git) return 1 ;;
  esac
  for allowed in "$@"; do
    allowed="${allowed%/}"
    if [ "$path" = "$allowed" ] || [ "${path#"$allowed"/}" != "$path" ]; then
      return 0
    fi
  done
  return 1
}

cmd_make() {
  local patch="$1"
  shift
  [ "$#" -gt 0 ] || die "make needs at least one PATH"
  git add -A -- "$@"
  if git diff --cached --quiet -- "$@"; then
    : >"$patch"
    echo "changed=false"
    return 0
  fi
  git diff --cached --binary --no-renames --full-index -- "$@" >"$patch"
  echo "changed=true"
}

cmd_apply() {
  local patch="$1"
  shift
  [ "$#" -gt 0 ] || die "apply needs at least one PATH"
  [ -s "$patch" ] || die "$patch is empty or missing"

  # Only regular files: no symlink (120000) and no submodule (160000), in
  # either the old or the new mode. A rename or copy cannot appear in a patch
  # written with --no-renames, so one is refused too.
  if grep -Eq '^(new file mode|deleted file mode|old mode|new mode|index [0-9a-f]+\.\.[0-9a-f]+) (120000|160000)$' "$patch"; then
    die "$patch changes a symlink or a submodule; refused"
  fi
  if grep -Eq '^(rename|copy) (from|to) ' "$patch"; then
    die "$patch renames or copies a file; refused"
  fi

  local count=0 rec path
  while IFS= read -r -d '' rec; do
    # --numstat -z prints "added<TAB>deleted<TAB>path" per file.
    path="${rec#*$'\t'}"
    path="${path#*$'\t'}"
    if ! path_allowed "$path" "$@"; then
      die "$patch touches $path, which is outside $*; refused"
    fi
    count=$((count + 1))
  done < <(git apply --numstat -z -- "$patch")
  # The exit status of `git apply` inside < <(...) is not seen. A patch it
  # cannot read yields no records, and the count check below refuses it.
  [ "$count" -gt 0 ] || die "$patch touches no file"

  git apply --index --whitespace=nowarn -- "$patch"
  echo "regenerated-patch: applied $count file(s) under $*" >&2
}

self_test() {
  local failures=0 tmp script
  script="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
  tmp="$(mktemp -d)"
  trap 'rm -rf "$tmp"' RETURN

  expect() {
    # $1 = pass|fail, $2 = label, rest = command.
    local want="$1" label="$2"
    shift 2
    if "$@" >/dev/null 2>&1; then
      [ "$want" = pass ] || {
        echo "FAIL: $label (expected a refusal)"
        failures=$((failures + 1))
      }
    else
      [ "$want" = fail ] || {
        echo "FAIL: $label (expected success)"
        failures=$((failures + 1))
      }
    fi
  }

  repo() {
    rm -rf "$tmp/$1"
    git init -q "$tmp/$1"
    git -C "$tmp/$1" config user.name t
    git -C "$tmp/$1" config user.email t@example.invalid
    mkdir -p "$tmp/$1/out" "$tmp/$1/src"
    printf 'old\n' >"$tmp/$1/out/a.txt"
    printf 'gone\n' >"$tmp/$1/out/b.txt"
    printf 'code\n' >"$tmp/$1/src/main.js"
    git -C "$tmp/$1" add -A
    git -C "$tmp/$1" commit -q -m base
  }

  # make, then apply on a clean copy: new, changed, deleted and binary files.
  repo build
  printf 'new\n' >"$tmp/build/out/a.txt"
  rm "$tmp/build/out/b.txt"
  printf '\000\001\002' >"$tmp/build/out/c.bin"
  printf 'tampered\n' >"$tmp/build/src/main.js"
  (cd "$tmp/build" && "$script" make "$tmp/p.patch" out) >"$tmp/out.txt"
  expect pass "make reports a change" grep -qx 'changed=true' "$tmp/out.txt"
  expect fail "make leaves out a change outside PATH" grep -q 'src/main.js' "$tmp/p.patch"
  repo land
  expect pass "apply accepts a patch inside PATH" \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/p.patch' out"
  expect pass "apply wrote the new content" grep -qx new "$tmp/land/out/a.txt"
  expect fail "apply deleted the removed file" test -e "$tmp/land/out/b.txt"
  expect pass "apply staged the binary file" sh -c "cd '$tmp/land' && git diff --cached --name-only | grep -qx out/c.bin"

  # make with nothing to do.
  repo idle
  (cd "$tmp/idle" && "$script" make "$tmp/empty.patch" out) >"$tmp/out.txt"
  expect pass "make reports no change" grep -qx 'changed=false' "$tmp/out.txt"
  repo land
  expect fail "apply refuses an empty patch" \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/empty.patch' out"

  # A patch that reaches outside PATH.
  repo evil
  printf 'x\n' >"$tmp/evil/src/main.js"
  git -C "$tmp/evil" diff --binary --no-renames --full-index >"$tmp/outside.patch"
  repo land
  expect fail "apply refuses a path outside PATH" \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/outside.patch' out"
  expect pass "a refused patch changes nothing" grep -qx code "$tmp/land/src/main.js"
  expect fail "apply refuses a prefix that is not a directory boundary" \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/outside.patch' sr"

  # A symlink inside PATH.
  repo link
  ln -s /etc/passwd "$tmp/link/out/link"
  git -C "$tmp/link" add -A
  git -C "$tmp/link" diff --cached --binary --no-renames --full-index >"$tmp/link.patch"
  repo land
  expect fail "apply refuses a symlink" \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/link.patch' out"

  # A path that climbs out of the tree.
  printf 'diff --git a/out/../src/main.js b/out/../src/main.js\n--- a/out/../src/main.js\n+++ b/out/../src/main.js\n@@ -1 +1 @@\n-code\n+x\n' >"$tmp/climb.patch"
  repo land
  expect fail "apply refuses a path with .." \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/climb.patch' out"

  # An exact file as PATH.
  repo file
  printf 'new\n' >"$tmp/file/out/a.txt"
  (cd "$tmp/file" && "$script" make "$tmp/file.patch" out/a.txt) >/dev/null
  repo land
  expect pass "apply accepts an exact file PATH" \
    sh -c "cd '$tmp/land' && '$script' apply '$tmp/file.patch' out/a.txt"

  if [ "$failures" -ne 0 ]; then
    echo "regenerated-patch self-test: $failures failure(s)"
    return 1
  fi
  echo "regenerated-patch self-test: OK"
}

case "${1:-}" in
  make)
    [ "$#" -ge 3 ] || die "usage: $0 make PATCH PATH..."
    shift
    cmd_make "$@"
    ;;
  apply)
    [ "$#" -ge 3 ] || die "usage: $0 apply PATCH PATH..."
    shift
    cmd_apply "$@"
    ;;
  --self-test)
    self_test
    ;;
  *)
    die "usage: $0 make|apply PATCH PATH... | --self-test"
    ;;
esac
